/* Checked shallow-water API; production misfit adjoint generated by Tapenade.
 * Rusanov finite volumes, SSP-RK2, clamped open boundaries, no clipping.
 * See README.md for generation and binomial checkpointing details. */
#include "swe2d_4dvar.h"
#include "swe_primal.h"
#include "tapenade_out/swe_primal_b.h"
#include "adStack.h"
#include <math.h>
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#define G 9.81
#define HMIN 1.e-6
typedef struct { int nx, ny; double lx, ly, dx, dy; } Grid;
typedef struct { double *h, *hu, *hv; } Field;
static Field field(double *p,int n) { Field f={p,p+n,p+2*n}; return f; }
/* Tapenade's runtime tape and binomial scheduler have process-global state. */
static pthread_mutex_t adjoint_mutex=PTHREAD_MUTEX_INITIALIZER;
static void euler_update(const Field *u,Field *v,const Grid *g,double dt) {
  swe_euler(g->nx*g->ny,g->nx,g->ny,g->dx,g->dy,dt,u->h,v->h);
}
static int valid_args(int nx,int ny,double lx,double ly,double dt,int ns,int stride) {
  return nx>=2 && ny>=2 && nx<=4096 && ny<=4096 &&
    isfinite(lx) && lx>0 && isfinite(ly) && ly>0 && isfinite(dt) && dt>0 &&
    ns>0 && ns<=1000000 && stride>0 && ns%stride==0;
}
static int check_state(const Field *u,const Grid *g,double dt,double *diag) {
  double maxx=0,maxy=0;
  int n=g->nx*g->ny;
  for(int k=0;k<n;++k) {
    double h=u->h[k], m=u->hu[k], v=u->hv[k];
    if(!isfinite(h)||!isfinite(m)||!isfinite(v)||h<=HMIN) return 3;
    diag[0]=fmin(diag[0],h);
    double c=sqrt(G*h);
    maxx=fmax(maxx,fabs(m/h)+c); maxy=fmax(maxy,fabs(v/h)+c);
  }
  double cfl=dt*(maxx/g->dx+maxy/g->dy);
  diag[1]=fmax(diag[1],cfl);
  return cfl<=0.9 ? 0 : 4;
}
static int step_checked(const Field *u,Field *stage,Field *tmp,Field *out,
                        const Grid *g,double dt,double *diag) {
  int err=check_state(u,g,dt,diag);
  if(err) return err;
  euler_update(u,stage,g,dt);
  if((err=check_state(stage,g,dt,diag))) return err;
  euler_update(stage,tmp,g,dt);
  if((err=check_state(tmp,g,dt,diag))) return err;
  for(int k=0;k<3*g->nx*g->ny;++k) out->h[k]=0.5*(u->h[k]+tmp->h[k]);
  return check_state(out,g,dt,diag);
}
int swe_forward(const double *initial,int nx,int ny,double lx,double ly,
                double dt,int ns,int stride,double *checkpoints,double *diag) {
  if(!initial||!checkpoints||!diag||!valid_args(nx,ny,lx,ly,dt,ns,stride)) return 1;
  int n=nx*ny,err=0;
  size_t nd=3*(size_t)n, bytes=nd*sizeof(double);
  double *buf=calloc(4*nd,sizeof(double));
  if(!buf) return 2;
  Grid g={nx,ny,lx,ly,lx/nx,ly/ny};
  Field u=field(buf,n),stage=field(buf+nd,n),tmp=field(buf+2*nd,n),v=field(buf+3*nd,n);
  memcpy(u.h,initial,bytes); memcpy(checkpoints,initial,bytes);
  diag[0]=INFINITY; diag[1]=0;
  for(int s=1;s<=ns;++s) {
    if((err=step_checked(&u,&stage,&tmp,&v,&g,dt,diag))) break;
    Field swap=u;u=v;v=swap;
    if(s%stride==0) memcpy(checkpoints+(size_t)(s/stride)*nd,u.h,bytes);
  }
  free(buf);return err;
}
int swe_evaluate_binomial(const double *initial,int nx,int ny,double lx,double ly,
                 double dt,int ns,int stride,int m,const int *indices,
                 const double *obs,double sigma,int budget,double *cost,
                 double *gradient,double *diag) {
  if(!initial||!indices||!obs||!cost||!diag||m<1||!isfinite(sigma)||sigma<=0||
     budget<1||budget>90||!valid_args(nx,ny,lx,ly,dt,ns,stride)) return 1;
  int n=nx*ny,err=0;
  size_t nd=3*(size_t)n,bytes=nd*sizeof(double);
  for(int p=0;p<m;++p) if(indices[p]<0||indices[p]>=n) return 1;
  for(size_t p=0;p<(size_t)(ns/stride)*m;++p) if(!isfinite(obs[p])) return 1;
  /* Constant-storage validation pass. Every Euler/RK stage must be wet and
   * CFL-safe before the unchecked differentiated arithmetic is entered. */
  double *buf=calloc((gradient ? 6 : 4)*nd,sizeof(double));
  if(!buf) return 2;
  Grid g={nx,ny,lx,ly,lx/nx,ly/ny};
  Field u=field(buf,n),stage=field(buf+nd,n),tmp=field(buf+2*nd,n),v=field(buf+3*nd,n);
  memcpy(u.h,initial,bytes);
  diag[0]=INFINITY; diag[1]=0; *cost=0;
  for(int s=0;s<ns;++s) {
    if((err=step_checked(&u,&stage,&tmp,&v,&g,dt,diag))) break;
    Field swap=u;u=v;v=swap;
    if((s+1)%stride==0) swe_observation(n,m,s,stride,indices,obs,sigma,u.h,cost);
  }
  if(err) { *cost=INFINITY; free(buf); return err; }
  if(!isfinite(*cost)) { free(buf); return 5; }
  if(gradient) {
    memset(buf,0,6*bytes);
    double ad_cost=0,costb=1;
    pthread_mutex_lock(&adjoint_mutex);
    swe_misfit_b(n,nx,ny,g.dx,g.dy,dt,ns,stride,m,budget,indices,obs,sigma,
                 initial,gradient,buf,buf+3*nd,buf+nd,buf+4*nd,buf+2*nd,buf+5*nd,
                 &ad_cost,&costb);
    /* A balanced generated reverse pass leaves the byte tape empty. */
    if(adStack_getCurrentStackSize()!=0) err=5;
    pthread_mutex_unlock(&adjoint_mutex);
    for(size_t k=0;k<nd;++k) if(!isfinite(gradient[k])) {err=5;break;}
  }
  free(buf); return err;
}
int swe_evaluate(const double *initial,int nx,int ny,double lx,double ly,
                 double dt,int ns,int stride,int m,const int *indices,
                 const double *obs,double sigma,double *cost,double *gradient,double *diag) {
  return swe_evaluate_binomial(initial,nx,ny,lx,ly,dt,ns,stride,m,indices,obs,sigma,
                               8,cost,gradient,diag);
}
